// componentsDemoImageSrc is a real, tiny (40x30) PNG generated by Go's
// own image/png package, embedded as a data URI so ImageZoom's demo
// has no network dependency.
const componentsDemoImageSrc = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACgAAAAeCAIAAADRv8uKAAAANklEQVR4nOzNsQ3AIBDAQBevKPvPwoCMQAfNWe5van11/+nvSWAwGAwGg8FgMBgMPrcDAAD//57AAv++dIYpAAAAAElFTkSuQmCC"

var componentsSearchFruits = []string{"Apple", "Apricot", "Banana", "Blueberry", "Cherry"}

func filterFruits(query string) []string {
	if query == "" {
		return nil
	}
	var out []string
	q := strings.ToLower(query)
	for _, f := range componentsSearchFruits {
		if strings.Contains(strings.ToLower(f), q) {
			out = append(out, f)
		}
	}
	return out
}

const otpLength = 4

// wireOTPFocusAdvance attaches focus-advance behavior directly via
// domrt/html on each OTPInput box, since gox.Event carries no
// reference to the input element itself (see OTPInputProps' doc
// comment) -- the same split FileUploader/ContextMenu use for the
// parts a plain gox.EventHandler can't express.
func wireOTPFocusAdvance(document *html.Document) {
	for i := 0; i < otpLength; i++ {
		i := i
		box := document.GetElementByID(fmt.Sprintf("otp-%d", i))
		box.AddEventListener("input", js.FuncOf(func(this js.Value, args []js.Value) any {
			val := this.Get("value").String()
			switch {
			case val != "" && i+1 < otpLength:
				document.GetElementByID(fmt.Sprintf("otp-%d", i+1)).Focus()
			case val == "" && i > 0:
				document.GetElementByID(fmt.Sprintf("otp-%d", i-1)).Focus()
			}
			return nil
		}))
	}
}

