func containsString(list []string, v string) bool {
	for _, x := range list {
		if x == v {
			return true
		}
	}
	return false
}

func removeString(list []string, v string) []string {
	out := make([]string, 0, len(list))
	for _, x := range list {
		if x != v {
			out = append(out, x)
		}
	}
	return out
}

func chipNodes(st *componentsState, render func()) []gox.Node {
	var nodes []gox.Node
	for _, label := range st.chipLabels {
		l := label
		nodes = append(nodes, components.Chip(components.ChipProps{
			Label: l,
			OnRemove: func(gox.Event) {
				st.chipLabels = removeString(st.chipLabels, l)
				render()
			},
		}))
	}
	return nodes
}

