// wireComponentsFileUploader reads the file selected through
// FileUploader's input directly via domrt/html, since gox.Event
// carries no file data (see FileUploaderProps' doc comment in
// components/fileuploader.gox).
func wireComponentsFileUploader(document *html.Document) {
	input := document.GetElementByID("uploader-input").AsInput()
	input.AddEventListener("change", js.FuncOf(func(this js.Value, args []js.Value) any {
		go func() {
			files := input.Files()
			if len(files) == 0 {
				document.GetElementByID("file-result").SetTextContent("no file")
				return
			}
			f := browser.WrapFile(files[0])
			text, err := f.ReadAsText()
			if err != nil {
				document.GetElementByID("file-result").SetTextContent("error: " + err.Error())
				return
			}
			document.GetElementByID("file-result").SetTextContent(
				fmt.Sprintf("name=%s size=%d text=%s", f.Name(), f.Size(), text))
		}()
		return nil
	}))
}

// wireComponentsContextMenu opens the ContextMenu at the real click
// position reported by html.Element.OnContextMenu, since gox.Event
// carries no clientX/clientY (see components.ContextMenuProps' doc
// comment).
func wireComponentsContextMenu(document *html.Document, st *componentsState, render func()) {
	target := document.GetElementByID("contextmenu-target")
	target.OnContextMenu(func(x, y float64) {
		st.contextMenuOpen = true
		st.contextMenuX = x
		st.contextMenuY = y
		render()
	})
}

// mountComponentsSection mounts the components gallery into the
// "components-app" container and wires up the parts that need a real
// DOM reference (see wireComponentsFileUploader/wireComponentsContextMenu/wireOTPFocusAdvance).
func mountComponentsSection(document *html.Document) {
	container := document.GetElementByID("components-app")

	st := &componentsState{
		accordionOpen:    map[int]bool{0: true},
		radioSelected:    "b",
		dateValue:        "2024-01-15",
		colorValue:       "#336699",
		sliderValue:      30,
		chipLabels:       []string{"go", "wasm", "gox"},
		dropdownSelected: []string{"go"},
		paginationPage:   5,
		collabRole:       components.CollabEditor,
	}

	var root *domrt.Root
	var render func()
	render = func() {
		node := ComponentsApp(st, render)
		if root == nil {
			root = domrt.Mount(container.Element, node)
		} else {
			root.Update(node)
		}
	}
	render()

	wireComponentsFileUploader(document)
	wireComponentsContextMenu(document, st, render)
	wireOTPFocusAdvance(document)
}
